-- CySA+ (CS0-003) questions, part B: Domain 3 Incident Response (24q),
-- Domain 4 Reporting & Communication (21q).
insert into public.questions (id, cert, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
-- Domain 3: Incident Response & Management
('cy-q-055','cysa',3,'3.1','ordering',2,$q$Place the NIST incident response lifecycle phases in order.$q$,$q$["Preparation","Detection & Analysis","Containment, Eradication & Recovery","Post-Incident Activity"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$NIST SP 800-61 defines Preparation; Detection & Analysis; Containment, Eradication & Recovery; and Post-Incident Activity. It is a loop - lessons feed back into preparation.$q$),
('cy-q-056','cysa',3,'3.1','mcq',2,$q$What distinguishes an event from an incident?$q$,$q$["Events are always malicious","An incident violates security policy or threatens CIA and requires response","Events require legal notification","There is no difference"]$q$::jsonb,'1'::jsonb,$q$An event is any observable occurrence; an incident is an event (or series) that violates policy or threatens confidentiality, integrity, or availability - triggering the response process. Most events are benign.$q$),
('cy-q-057','cysa',3,'3.3','ordering',3,$q$Order these evidence sources from MOST to LEAST volatile for collection.$q$,$q$["CPU cache and registers","RAM contents","Network connections and running processes","Disk (files, swap)","Archived logs and backups"]$q$::jsonb,$q$[0,1,2,3,4]$q$::jsonb,$q$Order of volatility: CPU cache/registers vanish first, then RAM, then live network/process state, then disk, then archival logs/backups. Collect the most volatile first or you lose it at power-off.$q$),
('cy-q-058','cysa',3,'3.2','mcq',2,$q$Ransomware is spreading between servers. What is the IMMEDIATE priority?$q$,$q$["Root cause analysis","Containment - isolate affected hosts to stop the spread","Writing the final report","Rebuilding from backups"]$q$::jsonb,'1'::jsonb,$q$With an active, spreading threat, containment comes first - isolate to stop further damage. Eradication, recovery, and reporting follow. Analysis mid-spread wastes precious time.$q$),
('cy-q-059','cysa',3,'3.2','mcq',2,$q$Which correctly orders the sub-steps after detection?$q$,$q$["Recovery, containment, eradication","Containment, eradication, recovery","Eradication, recovery, containment","Recovery, eradication, containment"]$q$::jsonb,'1'::jsonb,$q$You contain to stop spread, eradicate the cause (malware, accounts, vulnerability), then recover validated systems to production. Recovering before eradication reintroduces the threat.$q$),
('cy-q-060','cysa',3,'3.3','mcq',2,$q$Why is a write blocker used during forensic imaging?$q$,$q$["To speed up the copy","To prevent any modification of the source media","To encrypt the evidence","To compress the image"]$q$::jsonb,'1'::jsonb,$q$A write blocker ensures the source media cannot be altered during imaging, preserving evidence integrity. Analysis is performed on the verified copy, never the original.$q$),
('cy-q-061','cysa',3,'3.3','mcq',2,$q$After imaging a drive, why are both the source and image hashed?$q$,$q$["To compress them","To prove the copy is identical and unaltered","To encrypt the data","To speed up analysis"]$q$::jsonb,'1'::jsonb,$q$Matching hashes (e.g., SHA-256) of source and image prove the copy is a faithful, unaltered duplicate - critical for admissibility and defensibility. Hashing does not compress or encrypt.$q$),
('cy-q-062','cysa',3,'3.3','mcq',2,$q$What does chain of custody document?$q$,$q$["The network topology","Who handled evidence, when, and how, in an unbroken record","The vulnerability severity","The patch history"]$q$::jsonb,'1'::jsonb,$q$Chain of custody is the continuous, documented record of evidence handling that preserves integrity and admissibility. Gaps can render evidence inadmissible.$q$),
('cy-q-063','cysa',3,'3.1','mcq',2,$q$What is the difference between a playbook and a runbook?$q$,$q$["They are identical","A playbook is scenario decision guidance; a runbook is step-by-step procedure","A runbook is for executives only","A playbook is a legal document"]$q$::jsonb,'1'::jsonb,$q$A playbook provides decision-oriented response guidance for a scenario (e.g., phishing); a runbook is the detailed step-by-step operational procedure. Playbooks reference/contain runbooks.$q$),
('cy-q-064','cysa',3,'3.4','mcq',2,$q$What is the PRIMARY goal of root cause analysis after an incident?$q$,$q$["Assign blame to an individual","Identify the underlying cause so the class of incident cannot recur","Calculate insurance payouts","Satisfy the auditor only"]$q$::jsonb,'1'::jsonb,$q$RCA finds the systemic underlying cause (missing control, flawed process) so corrective action prevents recurrence. Blame-seeking suppresses honest reporting and is explicitly not the goal.$q$),
('cy-q-065','cysa',3,'3.2','mcq',3,$q$Analysts contain a breach but skip full scoping before eradication. What is the MOST likely consequence?$q$,$q$["Faster recovery with no downside","Attacker persistence remains on unidentified systems and the intrusion returns","Improved evidence integrity","Automatic compliance"]$q$::jsonb,'1'::jsonb,$q$Without scoping the full extent of compromise, eradication misses attacker footholds on unidentified systems, and the intrusion resurfaces. Thorough scoping precedes eradication for exactly this reason.$q$),
('cy-q-066','cysa',3,'3.3','mcq',2,$q$Which evidence is recoverable ONLY from a memory capture, not a disk image?$q$,$q$["Installed program list","Running process injected code and encryption keys in use","File modification timestamps","Registry hives on disk"]$q$::jsonb,'1'::jsonb,$q$RAM holds live process memory, injected code, active network connections, and in-use encryption keys - all lost at power-off. Program lists, timestamps, and on-disk registry survive on the disk image.$q$),
('cy-q-067','cysa',3,'3.1','mcq',2,$q$What is a tabletop exercise?$q$,$q$["A live attack against production","A discussion-based walkthrough of an incident scenario to test plans","A vulnerability scan","A penetration test"]$q$::jsonb,'1'::jsonb,$q$A tabletop is a discussion-based exercise stepping through a scenario to test plans, roles, and communication without touching production - a low-risk way to find gaps before a real incident.$q$),
('cy-q-068','cysa',3,'3.4','mcq',2,$q$What is the purpose of a lessons-learned meeting?$q$,$q$["Punish those responsible","Document what happened and what to improve, feeding back into preparation","Close the incident without review","Generate marketing material"]$q$::jsonb,'1'::jsonb,$q$The lessons-learned/after-action review captures what happened, what worked and failed, and concrete improvements - closing the loop back into preparation. It is blameless to get honest input.$q$),
('cy-q-069','cysa',3,'3.1','mcq',2,$q$Which role in a CSIRT owns overall coordination and decision authority during an incident?$q$,$q$["Forensic analyst","Incident commander","Legal counsel","Public relations"]$q$::jsonb,'1'::jsonb,$q$The incident commander coordinates the response and holds decision authority; forensics, legal, and PR are specialized supporting roles that report into that coordination.$q$),
('cy-q-070','cysa',3,'3.2','mcq',2,$q$What is the difference between short-term and long-term containment?$q$,$q$["Short-term is permanent; long-term is temporary","Short-term is immediate isolation; long-term is hardened interim measures allowing continued operation","They are the same","Long-term means doing nothing"]$q$::jsonb,'1'::jsonb,$q$Short-term containment is immediate isolation to stop damage; long-term containment applies hardened temporary fixes so business can continue while a clean rebuild is prepared.$q$),
('cy-q-071','cysa',3,'3.3','mcq',2,$q$What is data carving in digital forensics?$q$,$q$["Encrypting evidence","Recovering files by content signatures when filesystem metadata is missing","Deleting attacker files","Compressing disk images"]$q$::jsonb,'1'::jsonb,$q$Data carving recovers files from raw disk or memory using header/footer content signatures, even when filesystem metadata is deleted or corrupted. It does not encrypt, delete, or compress.$q$),
('cy-q-072','cysa',3,'3.4','mcq',2,$q$An incident exposed EU residents'' personal data. Which obligation is MOST directly triggered?$q$,$q$["PCI DSS quarterly scan","GDPR breach notification (within 72 hours)","SOC 2 renewal","ISO 27001 certification"]$q$::jsonb,'1'::jsonb,$q$GDPR requires notifying the supervisory authority of a personal-data breach within 72 hours of awareness. PCI scans, SOC 2, and ISO certification are unrelated to this specific notification trigger.$q$),
('cy-q-073','cysa',3,'3.1','mcq',2,$q$What is incident triage?$q$,$q$["Rebuilding servers","Classifying and prioritizing incidents by impact and urgency to allocate resources","Writing the final report","Patching vulnerabilities"]$q$::jsonb,'1'::jsonb,$q$Triage ranks incidents by business impact and urgency so responders focus on the most damaging first. It precedes deep analysis, recovery, and reporting.$q$),
('cy-q-074','cysa',3,'3.3','mcq',3,$q$An analyst must build a timeline of attacker activity. Which is the BEST primary source?$q$,$q$["Executive summaries","Correlated, timestamped log and artifact data","The vulnerability scanner","A network diagram"]$q$::jsonb,'1'::jsonb,$q$Timelines are reconstructed from correlated, timestamped logs and artifacts (auth logs, EDR events, file timestamps). Summaries and diagrams provide context but not the granular chronology.$q$),
('cy-q-075','cysa',3,'3.2','mcq',2,$q$Why might responders choose long-term containment instead of immediately rebuilding a critical production system?$q$,$q$["Rebuilding is always impossible","To keep essential business operations running while preparing a clean, validated rebuild","To avoid documentation","Because eradication is unnecessary"]$q$::jsonb,'1'::jsonb,$q$Critical systems can't always go offline instantly; long-term containment applies hardened interim controls so operations continue while a proper eradication and rebuild are staged. Eradication still happens.$q$),
('cy-q-076','cysa',3,'3.1','mcq',2,$q$Which document defines, in advance, who is notified and how during an incident?$q$,$q$["Vulnerability report","Communication plan","Asset inventory","Patch schedule"]$q$::jsonb,'1'::jsonb,$q$A communication plan predefines stakeholders, escalation paths, channels (including out-of-band), and messaging so coordination isn't improvised mid-crisis. The other documents serve different purposes.$q$),
('cy-q-077','cysa',3,'3.3','mcq',2,$q$What is legal hold?$q$,$q$["Encrypting all evidence","Suspending normal data deletion to preserve potentially relevant records","Deleting logs after an incident","Blocking a user account"]$q$::jsonb,'1'::jsonb,$q$A legal hold overrides routine retention/deletion to preserve data that may be relevant to litigation or investigation. Violating it risks spoliation sanctions.$q$),
('cy-q-078','cysa',3,'3.4','mcq',2,$q$Why is a blameless culture important in post-incident review?$q$,$q$["It speeds up patching","Fear of blame hides root causes; blameless review surfaces the truth needed to improve","It reduces licensing costs","It eliminates the need for logs"]$q$::jsonb,'1'::jsonb,$q$If people fear punishment, they conceal mistakes and you never learn the real cause. Blameless review treats incidents as systems failures, getting honest input to fix the underlying gaps.$q$),
-- Domain 4: Reporting & Communication
('cy-q-079','cysa',4,'4.1','mcq',2,$q$Why must a vulnerability report be tailored to its audience?$q$,$q$["To make it longer","Executives need risk/business impact; technical teams need specific findings and steps","Regulations forbid a single format","To hide the findings"]$q$::jsonb,'1'::jsonb,$q$Executives need business-risk framing and trends to make decisions; engineers need CVEs, affected hosts, and remediation steps to act. A single format serves neither well.$q$),
('cy-q-080','cysa',4,'4.1','mcq',2,$q$Which is a meaningful vulnerability management KPI?$q$,$q$["Number of monitors in the SOC","Mean time to remediate (MTTR) against SLA","Office square footage","Number of coffee machines"]$q$::jsonb,'1'::jsonb,$q$MTTR against SLA measures how quickly vulnerabilities are fixed relative to commitments - a core performance indicator. The other options are irrelevant to security performance.$q$),
('cy-q-081','cysa',4,'4.1','mcq',2,$q$What does a remediation SLA specify?$q$,$q$["The scanner brand","The timeframe to remediate by severity (e.g., criticals within 15 days)","The programming language","The office hours"]$q$::jsonb,'1'::jsonb,$q$A remediation SLA sets committed timeframes to fix findings by severity; reporting tracks compliance against it. It is not about tools, languages, or schedules.$q$),
('cy-q-082','cysa',4,'4.2','mcq',2,$q$Why do incident responders sometimes use out-of-band communication?$q$,$q$["It is cheaper","If attackers are in the network/email, they could read response coordination","It is required by GDPR","It improves Wi-Fi speed"]$q$::jsonb,'1'::jsonb,$q$If the primary network or email is compromised, attackers can read the team's coordination and react. Out-of-band channels keep response planning hidden from an intruder.$q$),
('cy-q-083','cysa',4,'4.2','mcq',2,$q$Which stakeholders typically must be identified in an incident communication plan?$q$,$q$["Only the IT help desk","Management, legal, PR, affected users, and potentially regulators/law enforcement","Only external vendors","Only the SOC analysts"]$q$::jsonb,'1'::jsonb,$q$Effective communication plans identify all relevant stakeholders - leadership, legal, PR, affected parties, regulators, and law enforcement - and what each needs to know and when.$q$),
('cy-q-084','cysa',4,'4.1','mcq',2,$q$What is the value of trend analysis in security reporting?$q$,$q$["It replaces remediation","It shows whether posture is improving or degrading over time to guide investment","It hides bad news","It is required by CVSS"]$q$::jsonb,'1'::jsonb,$q$Trend analysis (recurring vulns, MTTR direction, open criticals over time) reveals whether the program is getting better or worse, informing process changes and investment decisions.$q$),
('cy-q-085','cysa',4,'4.1','mcq',2,$q$A report combines severity, exposure, and asset value into one prioritized number. What is this?$q$,$q$["A CVE","A risk score","A hash","A subnet mask"]$q$::jsonb,'1'::jsonb,$q$A risk score blends severity with exposure and asset value into a single, actionable, trackable number for stakeholders. A CVE is an identifier, not a prioritization score.$q$),
('cy-q-086','cysa',4,'4.2','mcq',2,$q$What is the difference between declaring and escalating an incident?$q$,$q$["They are identical","Declaration formally recognizes an incident and triggers the plan; escalation raises severity/involvement","Escalation ends the incident","Declaration is only for executives"]$q$::jsonb,'1'::jsonb,$q$Declaration is the formal recognition that an event is an incident, activating the response plan; escalation raises severity and pulls in more resources/leadership as impact grows.$q$),
('cy-q-087','cysa',4,'4.1','mcq',2,$q$Which is a compliance report''s primary audience?$q$,$q$["Attackers","Auditors, regulators, and customers verifying controls meet a standard","Marketing only","The general public"]$q$::jsonb,'1'::jsonb,$q$Compliance reports provide evidence that controls meet a standard (PCI DSS, HIPAA, SOC 2) for auditors, regulators, and customers. They are not attacker- or marketing-facing.$q$),
('cy-q-088','cysa',4,'4.2','mcq',2,$q$Why should incident reports include a root cause and corrective actions section?$q$,$q$["To increase page count","So leadership can approve systemic fixes that prevent recurrence","To assign blame","To satisfy the attacker"]$q$::jsonb,'1'::jsonb,$q$Documenting root cause and corrective actions lets leadership approve and fund the systemic changes that stop recurrence - the point of reporting is improvement, not blame or length.$q$),
('cy-q-089','cysa',4,'4.1','mcq',2,$q$What is the difference between a metric and a KPI?$q$,$q$["Nothing","A metric is any measurement; a KPI is a goal-linked metric indicating performance","A KPI is always financial","A metric is always red"]$q$::jsonb,'1'::jsonb,$q$Every KPI is a metric, but a KPI is specifically tied to a goal and indicates performance (e.g., % criticals remediated within SLA). Not every metric is a KPI.$q$),
('cy-q-090','cysa',4,'4.2','mcq',2,$q$Which remediation inhibitor should reporting surface so stakeholders can weigh it?$q$,$q$["The finding has a CVE ID","Patching would interrupt a business-critical process","The scanner is credentialed","The asset is inventoried"]$q$::jsonb,'1'::jsonb,$q$Business process interruption, degrading functionality, legacy dependencies, and MOUs/SLAs are inhibitors stakeholders must weigh. A CVE, credentialed scans, and inventory are not inhibitors.$q$),
('cy-q-091','cysa',4,'4.1','mcq',2,$q$What is action item tracking in reporting?$q$,$q$["Listing findings with no follow-up","Assigning owners and due dates and following findings to closure","Deleting old reports","Renaming vulnerabilities"]$q$::jsonb,'1'::jsonb,$q$Tracking assigns each finding an owner and deadline and follows it to closure - reporting without accountability changes nothing. It is the bridge from insight to fixed risk.$q$),
('cy-q-092','cysa',4,'4.2','mcq',2,$q$Why is evidence retention important beyond the immediate incident?$q$,$q$["It fills disk space","It keeps reports defensible and lets investigations be revisited or used in court","It speeds up the network","It is never needed"]$q$::jsonb,'1'::jsonb,$q$Retaining logs, images, and artifacts per policy or legal hold keeps reports defensible and supports later reinvestigation or legal use. Premature deletion destroys that capability.$q$),
('cy-q-093','cysa',4,'4.1','matching',2,$q$Match each reporting audience to what they primarily need.$q$,$q${"left":["Executives","Engineers","Auditors","Legal"],"right":["Business risk and trends","Specific findings and remediation steps","Evidence controls meet a standard","Breach notification and preservation obligations"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Executives need business risk and trends; engineers need specific findings and fix steps; auditors need evidence of control compliance; legal needs notification duties and evidence preservation. Tailoring is the core of Domain 4.$q$),
('cy-q-094','cysa',4,'4.1','mcq',3,$q$Recurring appearance of the same vulnerability class across quarterly reports MOST likely indicates what?$q$,$q$["The scanner is broken","A systemic process or root-cause gap, not just isolated findings","Attackers are winning","Reports should be discontinued"]$q$::jsonb,'1'::jsonb,$q$Recurrence signals a systemic gap - a flawed build process, missing secure-coding standard, or unpatched golden image - that reporting should escalate for a root-cause fix, not repeated one-off remediation.$q$),
('cy-q-095','cysa',4,'4.2','mcq',2,$q$Which is the BEST reason to define escalation paths before an incident?$q$,$q$["To slow the response","So severity increases route to the right decision-makers without confusion mid-crisis","To avoid documentation","To reduce the number of analysts"]$q$::jsonb,'1'::jsonb,$q$Predefined escalation paths ensure that as an incident grows, the right leaders and resources are engaged quickly and unambiguously - improvised escalation wastes time during a crisis.$q$),
('cy-q-096','cysa',4,'4.1','mcq',2,$q$A monthly report shows MTTR for critical vulnerabilities rising over six months. What does this tell leadership?$q$,$q$["Security is improving","Remediation is getting slower and the process needs attention","Nothing actionable","The scanner should be disabled"]$q$::jsonb,'1'::jsonb,$q$Rising MTTR means critical fixes are taking longer - a degrading trend that signals resource, process, or prioritization problems leadership should address. It is a clear call to action.$q$),
('cy-q-097','cysa',4,'4.2','mcq',2,$q$What is a holding statement in incident communication?$q$,$q$["A final legal verdict","A pre-approved initial message acknowledging an issue while facts are confirmed","A vulnerability score","A firewall rule"]$q$::jsonb,'1'::jsonb,$q$A holding statement is a prepared, approved initial communication that acknowledges an incident without over-committing on unconfirmed details - buying time while facts are established.$q$),
('cy-q-098','cysa',4,'4.1','mcq',2,$q$Which best demonstrates translating a technical finding into business terms for an executive?$q$,$q$["CVE-2024-1234 has CVSS 9.8 with network AV","This flaw could let attackers reach customer payment data; fixing it costs X, a breach could cost Y","The stack trace shows a null pointer","The scanner used plugin 55231"]$q$::jsonb,'1'::jsonb,$q$Executives need risk and money: what could happen to the business, the cost to fix, and the cost of inaction. Raw CVE/CVSS/stack-trace detail belongs in the engineer-facing report.$q$),
('cy-q-099','cysa',4,'4.2','mcq',2,$q$When should law enforcement typically be considered as a stakeholder?$q$,$q$["For every failed login","When an incident involves criminal activity such as major data theft or extortion","Never","Only for password resets"]$q$::jsonb,'1'::jsonb,$q$Law enforcement is engaged for incidents involving criminal activity - significant data theft, extortion/ransomware, nation-state activity - per the communication plan. Routine events don't warrant it.$q$),
('cy-q-100','cysa',4,'4.1','mcq',2,$q$What is the purpose of assigning a risk owner in vulnerability reporting?$q$,$q$["To have someone to blame","To give an accountable decision-maker authority over treatment (fix, accept, mitigate)","To increase headcount","To satisfy the scanner"]$q$::jsonb,'1'::jsonb,$q$A risk owner is the accountable party who can decide and authorize treatment (remediate, mitigate, or formally accept). Without an owner, findings stall with no one empowered to act.$q$);
